import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>你的GIF太大了，发不出去。Discord拒绝它，页面加载很慢，聊天软件不让上传。</p>\n<p>压缩GIF大概只要两分钟。你选一个预设，调整调色板和缩放，预览动画，再下载更小的文件。</p>\n<p>这篇指南会走完每一步，从打开工具到在原位置检查完成后的GIF。</p>\n<h2 id=\"what-you-need\">开始之前需要准备什么？</h2>\n<p>你需要原始的GIF文件。从聊天软件里下载的GIF可能已经被压缩过，条件允许时用源文件。</p>\n<p>知道必须达到的大小上限。Discord、Slack和网站各有自己的上限，目标决定了设置。</p>\n<p>知道GIF会在哪里显示。显示得很小的贴纸，需要的数据比铺满博客文章的GIF少得多。</p>\n<p>原图保存好。千万别用压缩版覆盖它，万一要换设置重试还能找回来。</p>\n<h2 id=\"step-1-open\">第一步：打开GIF压缩工具</h2>\n<p>在浏览器里打开<a href=\"/zh/yasuo-gif/\">GIF压缩工具</a>。不需要账号，也不用安装。</p>\n<p>工具完全在你的设备上运行。动画在本地处理，永远不会上传到服务器。</p>\n<p>手机上操作也一样。点一下上传区域，从文件里选GIF就行。</p>\n<p>如果你经常压缩GIF，可以把页面加入收藏。表情GIF和片段是大多数人经常有的需求。</p>\n<h2 id=\"step-2-upload\">第二步：上传GIF</h2>\n<p>把GIF拖到上传区域，或者点一下浏览选择。工具会读取动画，包括它的帧、时间和循环设置。</p>\n<p>等GIF完全加载进来。大文件要花几秒钟，工具需要拿到每一帧才能工作。</p>\n<p>查看页面上显示的原始信息。改任何东西之前，先记下文件大小、尺寸和帧数。</p>\n<p>GIF加载不进来时，检查文件。损坏的下载，或者改名成GIF、其实不是GIF的文件，都会在这里失败。</p>\n<h2 id=\"step-3-preset\">第三步：选择预设</h2>\n<p>大多数GIF选均衡。它会缩小调色板、删掉一些帧、合理缩放，得到很好的中间值。</p>\n<p>GIF必须保持好看时选轻度。它会温和地缩小调色板，保持动画流畅。</p>\n<p>文件必须塞进严格上限时选最大压缩。它会把每个杠杆都推到底，做出来最小的文件。</p>\n<p>预设设定的是起点。选了预设之后，调色板、缩放和帧率都可以单独调整。</p>\n<h2 id=\"step-4-adjust\">第四步：调整调色板、缩放和帧数</h2>\n<p>按内容设定调色板。照片用128或256色，扁平图形和卡通用64或32色。</p>\n<p>按显示尺寸设定输出缩放。显示400像素宽的GIF，文件里没必要做到1000像素。</p>\n<p>GIF很长时才调整帧率。删帧对录屏和缓慢的动画帮助最大。</p>\n<p>一次只改一个设置。所有东西一起改，就看不出来到底是哪个调整起了作用。</p>\n<h2 id=\"step-5-run\">第五步：运行压缩</h2>\n<p>启动压缩，看着进度跑。工具会处理这些帧，做出更小的GIF。</p>\n<p>大GIF比小GIF花的时间更长。20MB的片段比2MB的表情需要更多的处理时间。</p>\n<p>工具运行时不要关闭标签页。工作是在你的浏览器里进行的，关闭页面会停止压缩。</p>\n<p>完成时，工具会显示新的文件大小和省下的百分比。普通的GIF能减少一半或更多。</p>\n<h2 id=\"step-6-preview\">第六步：预览动画</h2>\n<p>下载之前预览压缩后的GIF。至少看完一个完整的循环。</p>\n<p>先检查时间。动画应该和原来一样的速度播放，既不赶、也不拖。</p>\n<p>再检查颜色。照片类GIF在小调色板下可能出现色带，图形应该保持干净。</p>\n<p>最后检查流畅度。删帧会让快速动作变得一顿一顿，缓慢的动画依然流畅。</p>\n<p>如果有并排视图，一定要用。原图和压缩版放在一起看，损伤很容易发现。</p>\n<h2 id=\"step-7-download\">第七步：下载并测试</h2>\n<p>下载压缩好的GIF。文件名会标明它是压缩过的版本。</p>\n<p>在设备上检查文件大小。确认它符合将要使用的平台的上限。</p>\n<p>在它将要生活的地方测试GIF。先发给自己，在Discord上试试，或者打开它将要出现的页面，看着它播放。</p>\n<p>原文件保存好。压缩后的GIF出了问题，可以从原图重试，不用到处找。</p>\n<h2 id=\"fixing-problems\">常见问题的修复方法</h2>\n<p>GIF还是塞不进去时，进一步降低缩放。尺寸减半，文件大小会大幅下降。</p>\n<p>颜色看起来不对时，提高调色板。32色的照片类GIF色带会很严重，128色能修复它。</p>\n<p>动画播放一顿一顿时，恢复一些被删掉的帧。快速动作需要更多帧才能看起来流畅。</p>\n<p>文件反而变大了，说明原图本来就很小。直接用原文件，不要强行压缩。</p>\n<h2 id=\"discord-workflow\">实战：Discord用的GIF</h2>\n<p>先查你的账号在Discord上的上限。免费账号上传上限是8MB，目标决定了你的设置。</p>\n<p>把GIF上传到压缩工具，文件远超上限时选最大压缩。只超一点点时，均衡就够了。</p>\n<p>仔细预览动画。表情GIF很短，任何损伤在一个循环里都很容易发现。</p>\n<p>下载文件，先发给自己。确认它能上传、能正常播放，再分享到服务器里。</p>\n<h2 id=\"website-workflow\">实战：网站用的GIF</h2>\n<p>衡量GIF在页面上的作用。小小的装饰循环需要的数据，远比铺满全宽的演示少得多。</p>\n<p>上传GIF，选均衡。按显示宽度缩放，让文件不携带浪费的像素。</p>\n<p>按它将要出现的尺寸预览动画。放大看着不错的GIF，缩小时可能显得粗糙，反过来也一样。</p>\n<p>下载文件，上传到网站。发布后检查页面加载时间，确认确实改善了。</p>\n<p>长片段考虑用视频。超过十秒的GIF通常属于MP4，同样内容小得多。</p>\n<h2 id=\"phone-workflow\">实战：手机上操作</h2>\n<p>在手机浏览器里打开工具，点一下上传区域。从文件里选GIF。</p>\n<p>选预设，按GIF将要显示的位置调整缩放。小屏幕需要更小的文件。</p>\n<p>在手机屏幕上预览动画。下载之前，看完一个完整的循环。</p>\n<p>在“文件”应用里找到下载的文件，确认大小。然后分享到Discord、Slack或你选的聊天软件。</p>\n<h2 id=\"gif-sizes-by-platform\">各平台的大小上限</h2>\n<p>每个平台对GIF上传的上限都不一样。压缩之前知道上限，能省掉一次被拒的上传。</p>\n<p>Discord免费账号允许8MB，付费账号更多。GIF刚超上限时，只需要小幅缩小就能塞进去。</p>\n<p>Slack文件上传上限是1GB，但几MB以上的GIF在聊天窗口里播放起来很差。即使上限很宽裕，越小越好。</p>\n<p>网站没有固定的上限，但页面速度会惩罚沉重的GIF。博客文章里一张10MB的GIF，会让每个访客的页面都变慢。</p>\n<p>压缩之前，先查你的平台的上限。目标决定了预设，猜目标是浪费时间。</p>\n<h2 id=\"trimming-gifs\">压缩之前先剪短GIF</h2>\n<p>最有效的压缩是去掉内容。十秒的GIF剪到五秒，帧数立刻少了一半。</p>\n<p>剪掉无聊的开头和结尾。大多数片段都有一秒的铺垫和一秒的收尾，什么都没增加。</p>\n<p>保留最好的循环点。循环无缝的GIF感觉比实际更长，循环处有明显跳跃的GIF感觉就是坏的。</p>\n<p>先剪短，再压缩，不要反过来。压缩工具处理的是你给它的帧，帧越少，从一开始文件就越小。</p>\n<p>动画是GIF制作工具做的，在那里调整时间。源头删掉一帧，比压缩时删掉更干净。</p>\n<h2 id=\"preview-tips\">预览时发现问题的小技巧</h2>\n<p>在GIF将要显示的设备上预览。电脑上看着不错的GIF，手机上可能显得粗糙。</p>\n<p>至少看三个完整的循环。有些问题，比如循环点的卡顿，第一次播放时看不出来。</p>\n<p>在深色背景和浅色背景下都检查GIF。白色背景上看着不错的透明边缘，深色背景上可能会出现光晕。</p>\n<p>请别人也看一遍。一双新鲜的眼睛能发现你看了几次预览之后已经看习惯了的一顿一顿。</p>\n<p>预览是最便宜的质量控制。花两分钟看一看，能避免一次尴尬的分享。</p>\n<h2 id=\"gif-batch\">一次压缩多个GIF</h2>\n<p>GIF压缩工具一次处理一个动画。一组GIF要一个一个压缩，用同一个预设。</p>\n<p>整组保持设置一致。调色板和缩放混杂的表情包，分享到一起时看起来不整齐。</p>\n<p>记下第一个GIF管用的设置。其余的重复使用，不用每次都重新决定。</p>\n<p>静态图片批量处理时，用<a href=\"/zh/piliang-yasuo-tupian/\">批量图片压缩工具</a>。它批量处理照片，GIF需要单独的关注。</p>\n<p>批量压缩GIF比批量压缩照片慢，但结果更好。每个动画都值得单独预览、单独设置。</p>\n<h2 id=\"gif-quality-scale\">评判GIF画质：看什么？</h2>\n<p>评判压缩后的GIF看三件事：流畅度、颜色和锐度。每一项都有自己的失败方式，每一项也都有自己的修复方法。</p>\n<p>流畅度失败，是因为删帧太激进。快速动作变得一顿一顿，修复方法是恢复帧数。</p>\n<p>颜色失败，是因为调色板太小。皮肤出现色带、天空出现条纹，修复方法是更大的调色板。</p>\n<p>锐度失败，是因为缩放太小。细节变模糊、文字变虚，修复方法是更大的输出缩放。</p>\n<p>每次压缩后，三项都检查一遍。三项都通过的GIF可以分享了，任何一项没通过都需要再跑一次。</p>\n<h2 id=\"when-gif-fails\">GIF救不回来的时候</h2>\n<p>有些GIF怎么压都不够。一段又长、细节又多、照片类的片段，即使最大压缩也可能超过上限。</p>\n<p>这时就换格式。转成MP4或动态WebP，比任何GIF设置缩小的幅度都大得多。</p>\n<p>或者改内容。剪短片段、裁剪画面，或者降低帧率，能把做不到的GIF拉回到能做到的范围。</p>\n<p>或者接受上限。必须保持GIF、又必须很长的GIF，可能就是需要更高的上传上限，比如付费账号。</p>\n<p>知道什么时候停下来，也是技能的一部分。无休止的压缩尝试浪费的时间，换个格式就能省下来。</p>\n<h2 id=\"gif-future\">GIF在网上的未来</h2>\n<p>GIF很老，但不会消失。它通用的播放能力让它在聊天、邮件和社交媒体里一直活着。</p>\n<p>网站正在把长动画换成视频。自动播放的MP4表现得像GIF，重量却只有十分之一，这个转变已经在发生了。</p>\n<p>动态WebP正在成为中间地带。它保持了简单的播放，压缩却更好，浏览器支持现在已经很广了。</p>\n<p>短表情和贴纸用的GIF，还会再活很多年。没有其他格式能用这么少的力气、在这么多地方播放。</p>\n<p>实用的教训是，每项工作用合适的格式。通用短循环用GIF，高效的网页动画用WebP，更长的全部用MP4。</p>\n<h2 id=\"keep-practising-gif\">用真实的GIF不断练习</h2>\n<p>你压缩的每个GIF都能教会你一些东西。记下哪个预设管用、哪个缩放适合显示尺寸、文件大小发生了什么变化。</p>\n<p>这些笔记成了你的操作手册。下个GIF花的时间更少，因为上一个已经回答了那些问题。</p>\n<p>想看GIF压缩的完整指南，可以读<a href=\"/zh/blog/gif-ya-suo-qi-wan-zheng-zhi-nan/\">GIF压缩工具：完整指南</a>。想看格式对比，可以看<a href=\"/zh/blog/gif-vs-webp-vs-mp4-dong-tu-dui-bi/\">GIF、WebP、MP4：动态图片对比</a>。如果用照片制作GIF，<a href=\"/zh/zhizuo-gif/\">GIF制作工具</a>能先帮你做出来。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"怎么把GIF压到符合Discord的上传要求？","answer":"打开GIF压缩工具，上传GIF，远超8MB免费上限时选最大压缩。按显示尺寸降低缩放，预览动画。下载文件，确认它符合上限，先发给自己确认播放正常。"},{"question":"为什么我的GIF压缩后看起来一顿一顿？","answer":"删掉的帧太多了。删帧会保持总时长，但去掉中间帧，快速动作看起来就一顿一顿。用更少的删帧或更温和的预设重试，下载之前预览一个完整的循环。"},{"question":"能无损压缩GIF吗？","answer":"完全无损做不到，因为GIF压缩会去掉颜色、帧或像素。但用均衡预设加合适的调色板仔细压缩，损失几乎看不出来。从原文件开始，不要用已经压缩过的副本。"},{"question":"录屏GIF最好的调色板是多大？","answer":"录屏用扁平颜色和锐利文字，64色通常就很好。先试128色，文件还是太大时再降到64色。两种大小下文字都保持可读，这对录屏来说是最重要的。"},{"question":"GIF能压到多小？","answer":"要看长度、尺寸和内容。短表情GIF能降到1MB以下，十秒的片段即使最大压缩也可能超过5MB。特别长的片段，MP4或WebP视频是比GIF更好的格式。"},{"question":"压缩GIF会去掉它的透明背景吗？","answer":"不会，压缩过程中透明背景会被保留。透明区域在压缩后的文件里依然透明。缩小调色板会让柔和的透明边缘变粗糙，所以贴纸和叠加层用的GIF，调色板留得宽裕一点。"}];
